import csv, json
with open('csv/superhero.csv') as f: d=list(csv.DictReader(f))
with open('json/colour.json') as f: c=json.load(f)['records']
kc={r['id']:r['colour'] for r in c}
for r in d:
  if r['full_name']=='Karen Beecher-Duncan':
    eid=int(r['eye_colour_id']) if r['eye_colour_id'] else None
    print(f'Found: {r["full_name"]}, eye_colour_id: {eid}, colour: {kc.get(eid) if eid else "N/A"}')

